-- REVIEW-ONLY migration for the five sequence-backed core IDs confirmed by audit.
-- Converts these DEFAULT nextval primary keys to GENERATED BY DEFAULT AS IDENTITY
-- and restarts each identity sequence at MAX(primary_key) + 1.
-- This excludes crop_variety, roles, users, harvest_remarks, and manual lookup IDs.
-- Review before running. The final ROLLBACK is the default and leaves no changes.

-- Read-only preflight: confirm which primary keys are not identity columns.
WITH expected_keys(table_name, column_name) AS (
    VALUES
        ('farmer', 'farmer_id'), ('farm', 'farm_id'), ('crop', 'crop_id'),
        ('planting', 'planting_id'), ('harvest', 'harvest_id')
)
SELECT e.table_name, e.column_name, c.data_type, c.is_identity,
       c.identity_generation, c.column_default
FROM expected_keys AS e
LEFT JOIN information_schema.columns AS c
    ON c.table_schema = 'public'
   AND c.table_name = e.table_name
   AND c.column_name = e.column_name
ORDER BY e.table_name;

BEGIN;

DO $migration$
DECLARE
    item RECORD;
    identity_flag TEXT;
    primary_key_exists BOOLEAN;
    old_sequence TEXT;
    identity_sequence TEXT;
    next_value BIGINT;
BEGIN
    FOR item IN
        SELECT * FROM (VALUES
            ('farmer', 'farmer_id'),
            ('farm', 'farm_id'),
            ('crop', 'crop_id'),
            ('planting', 'planting_id'),
            ('harvest', 'harvest_id')
        ) AS keys(table_name, column_name)
    LOOP
        SELECT EXISTS (
            SELECT 1
            FROM pg_constraint AS pk
            JOIN pg_class AS tbl ON tbl.oid = pk.conrelid
            JOIN pg_namespace AS ns ON ns.oid = tbl.relnamespace
            JOIN LATERAL unnest(pk.conkey) AS key_column(attnum) ON TRUE
            JOIN pg_attribute AS attr
                ON attr.attrelid = tbl.oid AND attr.attnum = key_column.attnum
            WHERE ns.nspname = 'public'
              AND tbl.relname = item.table_name
              AND pk.contype = 'p'
              AND attr.attname = item.column_name
        ) INTO primary_key_exists;

        IF NOT primary_key_exists THEN
            RAISE EXCEPTION 'Expected primary key %.% was not found.', item.table_name, item.column_name;
        END IF;

        SELECT c.is_identity
        INTO identity_flag
        FROM information_schema.columns AS c
        WHERE c.table_schema = 'public'
          AND c.table_name = item.table_name
          AND c.column_name = item.column_name;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Missing expected primary-key column %.%.', item.table_name, item.column_name;
        END IF;

        IF identity_flag <> 'YES' THEN
            old_sequence := pg_get_serial_sequence(
                format('public.%I', item.table_name), item.column_name
            );

            -- Detach an existing serial sequence without dropping it.
            IF old_sequence IS NOT NULL THEN
                EXECUTE format('ALTER SEQUENCE %s OWNED BY NONE', old_sequence::regclass);
            END IF;

            EXECUTE format(
                'ALTER TABLE public.%I ALTER COLUMN %I DROP DEFAULT',
                item.table_name, item.column_name
            );
            EXECUTE format(
                'ALTER TABLE public.%I ALTER COLUMN %I ADD GENERATED BY DEFAULT AS IDENTITY',
                item.table_name, item.column_name
            );
        END IF;

        identity_sequence := pg_get_serial_sequence(
            format('public.%I', item.table_name), item.column_name
        );
        IF identity_sequence IS NULL THEN
            RAISE EXCEPTION 'No identity sequence found for %.%.', item.table_name, item.column_name;
        END IF;

        EXECUTE format(
            'SELECT COALESCE(MAX(%I), 0)::bigint + 1 FROM public.%I',
            item.column_name, item.table_name
        ) INTO next_value;

        -- ALTER SEQUENCE RESTART is transactional, so the final ROLLBACK
        -- restores the prior sequence state during review.
        EXECUTE format(
            'ALTER SEQUENCE %s RESTART WITH %s',
            identity_sequence::regclass, next_value
        );
    END LOOP;
END;
$migration$;

-- Change to COMMIT only after reviewing the preflight and approving the migration.
ROLLBACK;
